local UIFishPoolMainDialog = Class("UIFishPoolMainDialog")

function UIFishPoolMainDialog:__init() 
    ---@type FishingPlaceVo[]
    self._allFishPlace = {}                 --所有的渔场
end

function UIFishPoolMainDialog:__delete()
    self._allFishPlace = nil                 --所有的渔场
end


function UIFishPoolMainDialog:Awake()
    self.EventFishActivityClose = Events.AddListener(Constants.EventNames.FishActivityClose, Bind(self, self.OnFishActivityClose))

    --self.controller.MarkPoolable = true
    SetButtonAction(self.BtnLevelOfFish, Bind(self, self.OnBtnLevel))
    SetButtonAction(self.BtnFishAtlas, Bind(self, self.OnBtnIllustratedBook))
    --SetButtonAction(self.BtnFishing, Bind(self, self.OnBtnCardFishing))
    SetButtonAction(self.BtnNotice, Bind(self, self.OnBtnNotice))
    --SetButtonAction(self.FontStyleButton1, Bind(self, self.OnBtnFishBackPack))
    --SetButtonAction(self.FontStyleButton2, Bind(self, self.OnBtnExchange))
    --SetButtonAction(self.BtnCollection, Bind(self, self.OnBtnCollection))
end

function UIFishPoolMainDialog:InitData()
    self._allFishPlace = {}
    local t = FishingUtils.GetAllFishPlace()
    for k, v in pairs(t) do
        local isActivity = FishingUtils.IsActivityOpen(v.id)
        if isActivity then
            table.insert(self._allFishPlace, 1, v)
        else
            table.insert(self._allFishPlace, v)
        end
    end
    local actData = FishingUtils.GetFishPlaceDojoActivityData(self._allFishPlace[1].id)
    if actData then
        activityMgr:GetActivityComponent():SetActivityEnterTime(actData.id)
    end
    if GuideUtils.IsInGuiding() then
        table.sort(self._allFishPlace, function (a, b)
            return checkNumber(a.id) < checkNumber(b.id)
        end)
    end
end

function UIFishPoolMainDialog:OnFocus(focus)
    if focus then
        CfUtils.RefreshTopGoods({Constants.Currency.FishConsume})
    end
end

function UIFishPoolMainDialog:FillSelf()
    if not self._allFishPlace then
        return
    end
    
    if self.LoopList.IsListViewInit then
        GameUtils.ReloadData(self.LoopList, 0)
        GameUtils.ReloadData(self.LoopList, table.count(self._allFishPlace))
    else
        self.LoopList:InitListView(table.count(self._allFishPlace), Bind(self, self.OnRefreshIndex))
    end
    --self:FillLevelInfo()
end

--绘制i等级信息
function UIFishPoolMainDialog:FillLevelInfo()
    local level, exp = FishingUtils.GetCurLevelAndExp()
    CfUtils.FillText(self.TxtLv, level)
    local needExp = FishingUtils.GetUpLevelExp(level)
    if needExp then
        local showExp = FishingUtils.GetCurShowExp()
        self.ImgRound.fillAmount =  showExp/needExp--0.15 + showExp/needExp * (0.84 - 0.15) 
    else
        self.ImgRound.fillAmount = 1
    end
end

function UIFishPoolMainDialog:OnRefreshIndex(listView, index)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem(UIFishPlaceName)
    local data = self._allFishPlace[index + 1]
    
    ---@type UIFishPlaceNode
    local scr = CfUtils.GetLuaScr(cell, UIFishPlaceNode)
    if scr then
        scr:Refresh(data, index + 1)
    end
    return cell
end

