--合卡技能改变刷新
function UIFishPoolMainDialog:OnFishActivityClose()
    if self._isRefresh then
        return
    end
    self._isRefresh = true
    fishingComponent:FishingHomeReq(function()
        self:InitData()
        self:FillSelf()

        self._isRefresh = false
    end)
end


function UIFishPoolMainDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneFishCollection, self.BtnFishAtlas, true)
        --GameUtils.BindRedPoint(Constants.RedPointConst.PhoneFishHangUp, self.BtnFishing, true)

        CfUtils.RefreshTopGoods({Constants.Currency.FishConsume})
        fishingComponent:FishingHomeReq(function()
            self:InitData()
            self:FillSelf()
        end)
    end))
    return coWait
end

function UIFishPoolMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        Events.RemoveListener(Constants.EventNames.FishActivityClose, self.EventFishActivityClose)

        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneFishCollection)
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneFishHangUp)

        GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneFishActivityReward, FishingUtils.IsShowFishRedPoint() and 1 or 0)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFishPoolMainDialog
